#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<pair<string,int>> books(n);
    for (int i = 0; i < n; ++i) { cin >> books[i].first; books[i].second = i + 1; }
    auto cmp = [m](const pair<string,int>& a, const pair<string,int>& b) {
        for (int j = 0; j < m; ++j) {
            if (a.first[j] == b.first[j]) continue;
            if ((j + 1) % 2 == 1) return a.first[j] < b.first[j];
            return a.first[j] > b.first[j];
        }
        return a.second < b.second;
    };
    sort(books.begin(), books.end(), cmp);
    for (int i = 0; i < n; ++i) cout << books[i].second << (i + 1 == n ? '\n' : ' ');
    return 0;
}
